<?php
$savedPhotos = json_decode((string) ($instrutor['fotos'] ?? '[]'), true) ?: [];
$formLocais = old('local_nome') !== null ? array_map(static fn ($index) => [
    'nome' => old('local_nome')[$index] ?? '', 'endereco' => old('local_endereco')[$index] ?? '',
    'dias_horarios' => old('local_dias_horarios')[$index] ?? '', 'latitude' => old('local_latitude')[$index] ?? '',
    'longitude' => old('local_longitude')[$index] ?? '',
], array_keys((array) old('local_nome'))) : $locais;
if ($formLocais === []) $formLocais = [['nome' => '', 'endereco' => '', 'dias_horarios' => '', 'latitude' => '', 'longitude' => '']];
?>
<div class="admin-page-header"><div><h1><?= $editing ? 'Editar cadastro' : 'Novo cadastro' ?></h1><p>Um único perfil pode reunir todos os locais onde a pessoa ministra aulas.</p></div></div>
<form class="admin-card admin-form-card" action="<?= $action ?>" method="post" enctype="multipart/form-data"><div class="admin-card__body"><?= csrf_field() ?>
    <div class="row g-4">
        <div class="col-md-6"><label class="form-label" for="nome">Nome completo</label><input class="form-control" id="nome" name="nome" maxlength="150" value="<?= esc(old('nome', $instrutor['nome'] ?? ''), 'attr') ?>" required></div>
        <div class="col-md-3"><label class="form-label" for="apelido">Apelido</label><input class="form-control" id="apelido" name="apelido" maxlength="100" value="<?= esc(old('apelido', $instrutor['apelido'] ?? ''), 'attr') ?>" required></div>
        <div class="col-md-3"><label class="form-label" for="graduacao">Graduação</label><select class="form-select" id="graduacao" name="graduacao" required><option value="">Selecione</option><?php foreach ($graduacoes as $graduacao) : ?><option value="<?= esc($graduacao, 'attr') ?>" <?= old('graduacao', $instrutor['graduacao'] ?? '') === $graduacao ? 'selected' : '' ?>><?= esc($graduacao) ?></option><?php endforeach ?></select></div>
        <div class="col-12"><label class="form-label" for="biografia">Biografia</label><textarea class="form-control" id="biografia" name="biografia" rows="6" maxlength="5000"><?= esc(old('biografia', $instrutor['biografia'] ?? '')) ?></textarea><div class="form-text">Conte a trajetória e experiência na capoeira.</div></div>
        <div class="col-md-6"><label class="form-label" for="foto_perfil">Foto de perfil</label><?php if (!empty($instrutor['foto_perfil'])) : ?><div class="mb-2"><img class="admin-cover-preview" src="<?= base_url('uploads/' . $instrutor['foto_perfil']) ?>" alt="Foto atual de <?= esc($instrutor['apelido'], 'attr') ?>"></div><?php endif ?><input class="form-control" type="file" accept="image/jpeg,image/png,image/webp" name="foto_perfil" id="foto_perfil"><div class="form-text">JPG, PNG ou WebP, até 5 MB.</div></div>
        <div class="col-md-6"><label class="form-label" for="fotos">Galeria de fotos</label><input class="form-control" type="file" accept="image/jpeg,image/png,image/webp" name="fotos[]" id="fotos" multiple><div class="form-text">Você pode selecionar várias imagens, até 5 MB cada.</div><?php if ($savedPhotos) : ?><div class="mt-2 d-flex flex-wrap gap-2"><?php foreach ($savedPhotos as $photo) : ?><img class="admin-cover-preview" src="<?= base_url('uploads/' . $photo) ?>" alt="Foto da galeria" style="width:80px;height:60px;object-fit:cover"><?php endforeach ?></div><?php endif ?></div>
    </div>
    <hr class="my-4"><div class="d-flex align-items-center justify-content-between mb-3"><div><h2 class="h5 mb-1">Locais de aula</h2><p class="text-muted mb-0">Os pontos do mapa serão associados às coordenadas de cada local.</p></div><button class="admin-btn admin-btn--secondary" type="button" id="add-local">Adicionar local</button></div>
    <div id="locais-lista"><?php foreach ($formLocais as $local) : ?><div class="local-item border rounded p-3 mb-3"><div class="row g-3"><div class="col-md-4"><label class="form-label">Nome do local</label><input class="form-control" name="local_nome[]" maxlength="150" value="<?= esc($local['nome'] ?? '', 'attr') ?>" placeholder="Ex.: Academia Centro"></div><div class="col-md-8"><label class="form-label">Endereço</label><input class="form-control" name="local_endereco[]" maxlength="255" value="<?= esc($local['endereco'] ?? '', 'attr') ?>"></div><div class="col-md-6"><label class="form-label">Dias e horários</label><input class="form-control" name="local_dias_horarios[]" maxlength="255" value="<?= esc($local['dias_horarios'] ?? '', 'attr') ?>" placeholder="Segundas e quartas, 19h"></div><div class="col-md-2"><label class="form-label">Latitude</label><input class="form-control" name="local_latitude[]" inputmode="decimal" value="<?= esc($local['latitude'] ?? '', 'attr') ?>"></div><div class="col-md-2"><label class="form-label">Longitude</label><input class="form-control" name="local_longitude[]" inputmode="decimal" value="<?= esc($local['longitude'] ?? '', 'attr') ?>"></div><div class="col-md-2 d-flex align-items-end"><button class="admin-btn admin-btn--danger remover-local" type="button">Remover</button></div></div></div><?php endforeach ?></div>
    <template id="local-template"><div class="local-item border rounded p-3 mb-3"><div class="row g-3"><div class="col-md-4"><label class="form-label">Nome do local</label><input class="form-control" name="local_nome[]" maxlength="150" placeholder="Ex.: Academia Centro"></div><div class="col-md-8"><label class="form-label">Endereço</label><input class="form-control" name="local_endereco[]" maxlength="255"></div><div class="col-md-6"><label class="form-label">Dias e horários</label><input class="form-control" name="local_dias_horarios[]" maxlength="255" placeholder="Segundas e quartas, 19h"></div><div class="col-md-2"><label class="form-label">Latitude</label><input class="form-control" name="local_latitude[]" inputmode="decimal"></div><div class="col-md-2"><label class="form-label">Longitude</label><input class="form-control" name="local_longitude[]" inputmode="decimal"></div><div class="col-md-2 d-flex align-items-end"><button class="admin-btn admin-btn--danger remover-local" type="button">Remover</button></div></div></div></template>
    <div class="admin-form-actions"><a class="admin-btn admin-btn--secondary" href="<?= base_url('admin/instrutor') ?>">Cancelar</a><button class="admin-btn admin-btn--primary" type="submit">Salvar cadastro</button></div>
</div></form>
<script>document.getElementById('add-local').addEventListener('click',()=>document.getElementById('locais-lista').append(document.getElementById('local-template').content.cloneNode(true)));document.getElementById('locais-lista').addEventListener('click',e=>{if(e.target.classList.contains('remover-local'))e.target.closest('.local-item').remove()});</script>
